// store/modules/chat.js
export const chatModule = {
  namespaced: true,
  state: {
    recentChats: [] // 最近聊天列表
  },
  mutations: {
    // 添加或更新最近聊天用户
    ADD_RECENT_CHAT(state, user) {
      // 检查用户是否已在列表中
      const existingIndex = state.recentChats.findIndex(item => item.id === user.id);
      if (existingIndex !== -1) {
        // 如果存在，移到列表顶部
        state.recentChats.splice(existingIndex, 1);
      }
      // 添加到列表顶部
      state.recentChats.unshift(user);
      // 限制列表长度，例如最多保存50个最近聊天
      if (state.recentChats.length > 50) {
        state.recentChats.pop();
      }
    },
    // 初始化最近聊天列表
    INIT_RECENT_CHATS(state) {
      const recentChats = localStorage.getItem('recentChats');
      if (recentChats) {
        state.recentChats = JSON.parse(recentChats);
      }
    }
  },
  actions: {
    // 保存最近聊天列表到localStorage
    saveRecentChats({ state }) {
      localStorage.setItem('recentChats', JSON.stringify(state.recentChats));
    },
    // 对方发送消息时更新最近聊天列表（需要后端配合）
    updateRecentChatForReceiver({ commit }, user) {
      commit('ADD_RECENT_CHAT', user);
    }
  },
  getters: {
    getRecentChats: state => state.recentChats
  }
};
